# Let's use a different approach: iterative SAT solving with connectivity checking
from pysat.solvers import Glucose3
from itertools import combinations
from collections import Counter, deque

n = 18

given_edges = [
    (2,9), (0,10), (15,17), (12,15), (2,6), (3,17), (0,14), (11,13), (9,14), (6,12),
    (10,13), (1,10), (11,17), (10,16), (1,5), (6,14), (5,10), (1,9), (4,14), (15,16),
    (3,12), (13,16), (2,3), (10,15), (7,13), (6,16), (2,8), (3,10), (0,15), (2,16)
]

given_set = set()
for u, v in given_edges:
    given_set.add((min(u,v), max(u,v)))

# All possible edges
all_possible = []
for i in range(n):
    for j in range(i+1, n):
        if (i, j) not in given_set:
            all_possible.append((i, j))

edge_to_var = {}
for idx, (u, v) in enumerate(all_possible):
    edge_to_var[(u, v)] = idx + 1

var_to_edge = {idx + 1: (u, v) for idx, (u, v) in enumerate(all_possible)}
num_vars = len(all_possible)

def check_4_connected(edge_set):
    """Check if graph with given edges is 4-vertex-connected."""
    # Build adjacency
    adj = {v: set() for v in range(n)}
    for u, v in edge_set:
        adj[u].add(v)
        adj[v].add(u)

    # Check minimum degree >= 4
    for v in range(n):
        if len(adj[v]) < 4:
            return False, f"Vertex {v} has degree {len(adj[v])}"

    # Check vertex connectivity >= 4
    # For each set S of 3 vertices, check if G - S is connected
    for S in combinations(range(n), 3):
        S_set = set(S)
        remaining = [v for v in range(n) if v not in S_set]
        if not remaining:
            continue

        # BFS from first remaining vertex
        visited = set()
        queue = deque([remaining[0]])
        visited.add(remaining[0])

        while queue:
            curr = queue.popleft()
            for neighbor in adj[curr]:
                if neighbor not in S_set and neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(neighbor)

        if len(visited) != len(remaining):
            return False, f"Removing {S} disconnects graph"

    return True, "OK"

# Iterative approach: solve SAT, check connectivity, add blocking clause if not connected
solver = Glucose3()

# Degree constraints
degree = Counter()
for u, v in given_edges:
    degree[u] += 1
    degree[v] += 1

for v in range(n):
    if degree[v] < 4:
        needed = 4 - degree[v]
        incident = []
        for idx, (u, w) in enumerate(all_possible):
            if u == v or w == v:
                incident.append(idx + 1)
        from itertools import combinations as comb
        for subset in comb(incident, len(incident) - needed + 1):
            solver.add_clause(list(subset))

print("Starting iterative SAT solving...")
iteration = 0
max_iterations = 1000

while iteration < max_iterations:
    iteration += 1
    if not solver.solve():
        print("UNSATISFIABLE")
        break

    model = solver.get_model()

    # Build edge set from model
    edge_set = set(given_set)
    for lit in model:
        if lit > 0 and lit <= num_vars:
            u, v = var_to_edge[lit]
            edge_set.add((min(u,v), max(u,v)))

    # Check connectivity
    connected, msg = check_4_connected(edge_set)

    if connected:
        print(f"Found solution after {iteration} iterations!")
        print(f"Total edges: {len(edge_set)}")

        # Verify
        edge_list = sorted(edge_set)
        print("Edges:", edge_list)
        break
    else:
        # Add blocking clause: at least one edge that would fix this must be added
        # Find the problematic cut and add constraint
        # For now, just add a clause that at least one new edge must be different
        # Better: find the specific cut and add edges that would fix it

        # Parse the error message to find the problematic set S
        if "Removing" in msg:
            # Extract S from message
            parts = msg.split("Removing ")[1].split(" disconnects")[0]
            S = eval(parts)
            S_set = set(S)
            remaining = [v for v in range(n) if v not in S_set]

            # Find the connected components of G - S
            adj_temp = {v: set() for v in range(n)}
            for u, v in edge_set:
                adj_temp[u].add(v)
                adj_temp[v].add(u)

            visited = set()
            components = []
            for start in remaining:
                if start not in visited:
                    comp = set()
                    queue = deque([start])
                    visited.add(start)
                    comp.add(start)
                    while queue:
                        curr = queue.popleft()
                        for neighbor in adj_temp[curr]:
                            if neighbor not in S_set and neighbor not in visited:
                                visited.add(neighbor)
                                comp.add(neighbor)
                                queue.append(neighbor)
                    components.append(comp)

            # There must be at least 2 components. Add edges between them.
            # For each pair of components, there must be at least one edge
            if len(components) >= 2:
                # Add constraint: at least one edge between comp[0] and comp[1]
                clause = []
                for u in components[0]:
                    for v in components[1]:
                        if u < v:
                            edge = (u, v)
                        else:
                            edge = (v, u)
                        if edge in edge_to_var:
                            clause.append(edge_to_var[edge])
                        elif edge in given_set:
                            # This edge already exists, so this shouldn't happen
                            pass

                if clause:
                    solver.add_clause(clause)
                    if iteration % 100 == 0:
                        print(f"Iteration {iteration}: Added clause of size {len(clause)} for cut {S}")
                else:
                    print(f"Warning: No possible edges between components for cut {S}")
                    print(f"Components: {[sorted(c) for c in components]}")
        else:
            print(f"Iteration {iteration}: {msg}")
            # Add a random clause to force progress
            # Find a vertex with degree < 4 and force an edge
            degree_temp = Counter()
            for u, v in edge_set:
                degree_temp[u] += 1
                degree_temp[v] += 1
            for v in range(n):
                if degree_temp[v] < 4:
                    incident = []
                    for idx, (u, w) in enumerate(all_possible):
                        if (u == v or w == v) and (u, w) not in given_set:
                            incident.append(idx + 1)
                    if incident:
                        solver.add_clause(incident)
                        break
